<script setup lang="ts">
import { useDialogDraft } from '../dialog-draft'
import { useAdminListRoute } from '../navigation'
import { ref, watch } from 'vue'
import type { UserInfo } from '../api'
import { useAdminPage } from '../admin-page'
import { getClosures, reviewClosure, closureStatuses, choices, dateTime, type Closure } from '../growth'
const props = defineProps<{ user: UserInfo }>()
const items = ref<Closure[]>([]), total = ref(0), pageNumber = ref(1), status = ref('pending'), selected = ref<Closure | null>(null), dialog = ref(false), action = ref<'approve' | 'reject'>('reject'), reply = ref(''), confirmName = ref('')
const page = useAdminPage(async valid => { const result = await getClosures(status.value === 'all' ? '' : status.value, (pageNumber.value - 1) * 20); if (valid()) { items.value = result.items; total.value = result.total } }, () => { dialog.value = false })
const { error, notice, loading, busy } = page
const routeState = useAdminListRoute('accountClosures', { status, page: pageNumber }, () => { void page.load() })
watch(pageNumber, page.load); watch(status, () => { if (routeState.restoring) return; if (pageNumber.value === 1) void page.load(); else pageNumber.value = 1 })
function edit(item: Closure) { selected.value = item; action.value = 'reject'; reply.value = ''; confirmName.value = ''; error.value = ''; dialog.value = true }
function save() { if (!selected.value) return; void page.act(async valid => { await reviewClosure(props.user.id, selected.value!, action.value, reply.value.trim(), action.value === 'approve' && confirmName.value === selected.value!.account_name); if (valid()) { dialog.value = false; notice.value = action.value === 'approve' ? '账号已注销，个人数据已清理' : '审核结果已发送到用户消息中心'; await page.load() } }) }
const draft = useDialogDraft(dialog, () => [action.value, reply.value, confirmName.value], busy, '注销审核')
</script>
<template><section class="admin-section"><p class="text-sm text-muted mb-4">用户可在审核前撤回申请。审核通过会清理个人数据；未结订单和退款会阻止注销。</p><UAlert v-if="error" :title="error" color="error" class="notice" /><UAlert v-if="notice" :title="notice" color="success" class="notice" /><div class="section-toolbar"><USelect v-model="status" :items="[{ value: 'all', label: '全部申请' }, ...choices(closureStatuses)]" :disabled="loading" aria-label="注销申请状态" /><UButton label="刷新" variant="outline" :loading="loading" @click="page.load" /></div><div class="data-scroll"><table class="data-table"><thead><tr><th>账号</th><th>申请原因</th><th>状态</th><th>更新时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>{{ item.account_name }}</td><td class="comment-cell">{{ item.reason || '—' }}</td><td>{{ closureStatuses[item.status] }}</td><td>{{ dateTime(item.updated_at) }}</td><td><UButton :label="item.status === 'pending' ? '审核申请' : '查看结果'" variant="soft" @click="edit(item)" /></td></tr><tr v-if="!items.length"><td colspan="5">{{ loading ? '正在加载' : '暂无匹配申请' }}</td></tr></tbody></table></div><div class="table-footer"><span>共 {{ total }} 条申请</span><UPagination v-if="total > 20" v-model:page="pageNumber" :total="total" :items-per-page="20" :disabled="loading" /></div>
  <UModal v-model:open="draft.model.value" title="注销申请审核" :dismissible="!busy" :close="!busy"><template #body><form v-if="selected" id="closure-review" class="field-stack" @submit.prevent="save"><p><strong>{{ selected.account_name }}</strong> · {{ closureStatuses[selected.status] }}</p><p class="whitespace-pre-wrap">{{ selected.reason || '未填写原因' }}</p><template v-if="selected.status === 'pending'"><UFormField label="审核决定"><USelect v-model="action" :items="[{ value: 'reject', label: '暂不通过，回复原因' }, { value: 'approve', label: '通过并注销账号' }]" :disabled="busy" class="w-full" /></UFormField><UFormField label="处理说明" required><UTextarea v-model="reply" minlength="2" maxlength="500" required :disabled="busy" class="w-full" /></UFormField><template v-if="action === 'approve'"><UAlert color="warning" title="将永久清理此账号的个人数据并终止会员权益" description="注销不会自动退款。请核实订单与退款后再通过；已完成交易会匿名保留。" /><UFormField :label="'输入账号名「' + selected.account_name + '」确认'" required><UInput v-model="confirmName" :disabled="busy" autocomplete="off" class="w-full" /></UFormField></template></template><p v-else class="whitespace-pre-wrap">{{ selected.reply || '用户已撤回申请' }}</p><UAlert v-if="error" :title="error" color="error" /></form></template><template #footer><UButton label="关闭" color="neutral" variant="outline" :disabled="busy" @click="draft.setOpen(false)" /><UButton v-if="selected?.status === 'pending'" :label="action === 'approve' ? '确认注销账号' : '保存审核结果'" :color="action === 'approve' ? 'error' : 'primary'" type="submit" form="closure-review" :loading="busy" :disabled="busy || reply.trim().length < 2 || (action === 'approve' && confirmName !== selected.account_name)" /></template></UModal>
</section></template>
